"""Compare every GDS record byte except BGNLIB/BGNSTR timestamp payloads.
Reference: GDSTK library.cpp gds_timestamp/read_gds; no geometric XOR claim.
"""
import hashlib,json,sys
from pathlib import Path

def digest(path):
    data=Path(path).read_bytes(); normalized=bytearray(); offset=0; stamps=0
    while offset<len(data):
        if offset+4>len(data): raise ValueError('truncated record header')
        length=int.from_bytes(data[offset:offset+2],'big')
        if length<4 or length%2 or offset+length>len(data): raise ValueError('invalid record length')
        record=bytearray(data[offset:offset+length])
        if record[2] in (1,5):
            if length!=28 or record[3]!=2: raise ValueError('unexpected timestamp record')
            record[4:]=bytes(24); stamps+=1
        normalized.extend(record); offset+=length
    return {'raw_sha256':hashlib.sha256(data).hexdigest(),'timestamp_normalized_sha256':hashlib.sha256(normalized).hexdigest(),'timestamp_records':stamps,'size_bytes':len(data)}

if __name__=='__main__':
    a,b=(digest(p) for p in sys.argv[1:])
    print(json.dumps({'selected':a,'reproduced':b,'identical_except_timestamps':a['timestamp_normalized_sha256']==b['timestamp_normalized_sha256']},indent=2))
